const jitter = (r, amount) => (r - 0.5) * amount;

export default ($) => {
  let sys = particles("jets")
    .param("count", { value: 3, min: 1, max: 5 })
    .bounds({ width: 500, height: 200 })
    .maxParticles(3000)
