const MAX_SIZE = 6;
const clampSize = (s) => Math.min(MAX_SIZE, Math.max(1, s));

export default ($) => particles("smoke")
  .param("lift", { value: 40, min: 0, max: 100 })
  .bounds({ width: 300, height: 400 })
  .maxParticles(2000)
  .tick(1 / 20)
  .field("puff", { value: 0.5 })
