    p.puff = p.puff * 0.99;
  })
  .emitter("stack", { x: 150, y: 390, maxRate: 50 })
    .rate((t, live) => 30 - live * 0.1)
    .spawn((p, rng, i) => {
      p.pos = p.pos + vec2(i * 2, 0);
      p.life = 3 + rng() * 2;
      p.size = 1;
      counters.born++;
