  .field("fade", { value: 0 })
  .counter("fast")
  .force("float", (p, dt) => { p.vel = p.vel - vec2(0, 20) * dt; })
  .update((p, dt) => {
    p.fade = p.fade + dt;
    if (speedOf(p) > 100) { counters.fast += p.size; }
    if (p.fade > 2) { p.kill(); }
  })
  .emitter("core", { x: 100, y: 100, maxRate: 200, forces: [] })
    .rate((t, live) => (t < 1 ? $.burst : 0))
    .spawn((p, rng, i) => {
