  .param("spin", { value: 0.5, min: 0, max: 1 })
  .bounds({ width: 256, height: 256 })
  .maxParticles(800)
  .field("hue", { value: 0 })
  .field("phase", { value: 1 })
  .counter("lost")
  .force("swirl", (p, dt) => { p.vel = p.vel + twist(p, $.spin) * dt; })
  .force("slow", (p, dt) => { p.vel = p.vel / (1 + dt); })
