  .emitter("eye", { x: 128, y: 128, maxRate: 100 })
    .rate((t, live) => (live < 400 ? 100 : 0))
    .spawn((p, rng) => {
      p.vel = vec2(rng() - 0.5, rng() - 0.5) * 100;
      p.phase = 0.5 + rng();
      p.life = 4;
    });

