              ctx.error("K001", `param '${n}': value ${p.value} must lie within min..max`, { arg: 1, tip: "keep min <= value <= max" });
          },
        },
        field: {
          kind: "decl", as: "fields",
          args: [name("field"), data({ value: "number" })],
          check({ args: [n] }, ctx) {
