      check(record, ctx) {
        const emitters = record.emitter ?? [];
        if (emitters.length === 0) ctx.error("K007", "a Program needs at least one emitter", { tip: "add .emitter(\"name\", { x, y, maxRate })" });
        const b = record.bounds;
