        if (o.maxRate < 0) ctx.error("K009", "maxRate must be at least 0", { tip: "write maxRate >= 0" });
        const f = o.forces ?? [];
        if (new Set(f).size !== f.length) ctx.error("K010", "an emitter's forces list names a force twice", { tip: "list each force once" });
      },
    },
  },
});

